const reg = $('Load Client Homepages').all().map(i => i.json);
const fetched = $input.all().map(i => i.json);
const out = [];

// The Code node sandbox has no URL constructor, so parse by hand.
function parts(u) {
  const m = String(u || '').match(/^(https?:)\/\/([^\/?#]+)([^?#]*)/i);
  if (!m) return null;
  return { protocol: m[1], host: m[2], origin: m[1] + '//' + m[2], path: m[3] || '/' };
}
function baseHost(h) { return String(h || '').replace(/^www\./i, '').toLowerCase(); }

function resolve(href, base) {
  const h = String(href).trim();
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith('//')) return base.protocol + h;
  if (h.startsWith('/')) return base.origin + h;
  const dir = base.path.replace(/[^\/]*$/, '');
  return base.origin + dir + h;
}

for (let i = 0; i < reg.length; i++) {
  const r = reg[i];
  const html = String((fetched[i] || {}).html || '');

  if (html.length < 500) {
    out.push({ json: { ...r, link_count: 0, html_len: html.length, extract_status: 'html_too_short', link_list: '' } });
    continue;
  }

  const base = parts(r.watch_url);
  if (!base) {
    out.push({ json: { ...r, link_count: 0, html_len: html.length, extract_status: 'bad_base_url', link_list: '' } });
    continue;
  }
  const host = baseHost(base.host);

  const seen = {};
  const links = [];
  const re = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  let total = 0;
  let sameSite = 0;

  while ((m = re.exec(html)) !== null) {
    total++;
    const href = m[1].trim();
    if (!href || href.startsWith('#') || /^(mailto:|tel:|javascript:|data:)/i.test(href)) continue;

    let abs = resolve(href, base);
    const ap = parts(abs);
    if (!ap) continue;
    if (baseHost(ap.host) !== host) continue;
    sameSite++;

    if (/\.(jpg|jpeg|png|gif|svg|pdf|webp|ico|css|js)$/i.test(ap.path)) continue;

    abs = abs.split('#')[0];
    if (seen[abs]) continue;
    seen[abs] = true;

    const label = m[2].replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&amp;/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 70);
    links.push((label || '(no text)') + ' -> ' + abs);
    if (links.length >= 160) break;
  }

  out.push({ json: {
    ...r,
    link_count: links.length,
    anchors_total: total,
    same_site_anchors: sameSite,
    html_len: html.length,
    extract_status: links.length > 0 ? 'ok' : 'no_links',
    link_list: links.join('\n')
  } });
}

return out;

const src = $('Extract Internal Links').all().map(i => i.json);
const resp = $input.all().map(i => i.json);
const out = [];

for (let i = 0; i < src.length; i++) {
  const r = src[i];
  if (r.extract_status !== 'ok') continue;

  const raw = resp[i] || {};
  let pages = [];

  try {
    if (raw.error) throw new Error(raw.error.message || 'api error');
    const blocks = Array.isArray(raw.content) ? raw.content : [];
    const textBlock = blocks.find(b => b && b.type === 'text');
    if (!textBlock || !textBlock.text) throw new Error('no text block');
    const cleaned = textBlock.text.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
    const parsed = JSON.parse(cleaned);
    pages = Array.isArray(parsed.pages) ? parsed.pages : [];
  } catch (e) {
    continue;
  }

  for (const p of pages) {
    if (!p || !p.url || (p.confidence ?? 0) < 0.5) continue;
    if (String(p.url).replace(/\/$/, '') === String(r.watch_url).replace(/\/$/, '')) continue;
    out.push({ json: {
      client_id: r.client_id,
      client_firm: r.client_firm,
      market: r.market,
      practice_area: r.practice_area,
      competitor_name: r.competitor_name,
      watch_url: String(p.url).split('#')[0],
      page_label: String(p.page_label || p.category || 'page').slice(0, 40),
      active: true
    } });
  }
}

return out;
